def skeptical_consequence(conflict, premises, conclusion):
    if conclusion not in premises:
        return False
    for q in premises:
        if conflict.has_conflict(conclusion, q):
            return False
    return True

def iterated_revision(conflict, beliefs):
    while True:
        next_beliefs = {p for p in beliefs if skeptical_consequence(conflict, beliefs, p)}
        if next_beliefs == beliefs:
            return beliefs
        beliefs = next_beliefs
